html:
{{ letter_head }}

{%- set rows = doc.material_requests | selectattr("material_request") | list %}
{%- set approved_rows = rows | selectattr("decision", "equalto", "Approved") | list %}
{%- set rejected_rows = rows | selectattr("decision", "equalto", "Rejected") | list %}
{%- set recorded = doc.total_approved or doc.approved_by %}

{#- Density follows the row count, the same way the sales invoice format does:
    a 30 line request must not spill onto a second page for want of 2px. -#}
{%- set density = "" %}
{%- if rows | length > 18 %}{% set density = "ultra-compact" %}
{%- elif rows | length > 10 %}{% set density = "compact" %}
{%- endif %}

<style>
@page { size: A4; margin: 8mm 10mm 12mm 10mm; }

.cgm-fr { font-family: Arial, Helvetica, sans-serif; color: #171717; font-size: 10.25px; line-height: 1.3; background: #fff; }
.cgm-fr * { box-sizing: border-box; }

.cgm-fr .title { margin: 0; font-size: 22px; font-weight: 800; letter-spacing: 1.4px; text-transform: uppercase; }
.cgm-fr .subtitle { font-size: 9.5px; color: #6b6b6b; margin-top: 2px; letter-spacing: 0.3px; }

.cgm-fr .head { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.cgm-fr .head td { vertical-align: top; padding: 0; }

.cgm-fr .meta { border-collapse: collapse; margin-left: auto; }
.cgm-fr .meta td { padding: 0 0 1px; font-size: 10px; white-space: nowrap; }
.cgm-fr .meta .k { color: #8b1a1a; font-weight: 700; padding-right: 8px; }
.cgm-fr .meta .v { font-weight: 700; }

/* State is the first thing a reader needs: is this a request, or money already
   agreed? A chip says it without a sentence. */
.cgm-fr .chip { display: inline-block; padding: 2px 9px; border-radius: 999px; font-size: 9.5px;
  font-weight: 700; letter-spacing: 0.3px; text-transform: uppercase; border: 1px solid; }
.cgm-fr .chip-neutral { color: #475569; border-color: #cbd5e1; background: #f8fafc; }
.cgm-fr .chip-approved { color: #166534; border-color: #bbf7d0; background: #f0fdf4; }
.cgm-fr .chip-rejected { color: #9f1239; border-color: #fecdd3; background: #fff1f2; }

.cgm-fr .band { width: 100%; border-collapse: collapse; margin: 0 0 9px; border: 1px solid #e5e7eb; border-radius: 6px; overflow: hidden; }
.cgm-fr .band td { padding: 6px 9px; border-right: 1px solid #eef0f2; text-align: right; }
.cgm-fr .band td:first-child { text-align: left; }
.cgm-fr .band td:last-child { border-right: 0; }
.cgm-fr .band .lbl { display: block; font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; font-weight: 700; }
.cgm-fr .band .amt { display: block; font-size: 12.5px; font-weight: 800; margin-top: 1px; }
.cgm-fr .band .amt.out { color: #8b1a1a; }

.cgm-fr table.lines { width: 100%; border-collapse: collapse; }
.cgm-fr table.lines th { background: #f6f7f8; border-bottom: 1.5px solid #8b1a1a; padding: 5px 6px;
  font-size: 9px; text-transform: uppercase; letter-spacing: 0.4px; text-align: left; white-space: nowrap; }
.cgm-fr table.lines td { padding: 5px 6px; border-bottom: 1px solid #eef0f2; vertical-align: top; }
.cgm-fr table.lines tr { page-break-inside: avoid; }
.cgm-fr .num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
.cgm-fr .idx { text-align: right; color: #9aa5b1; width: 22px; }
/* A requisition number is a reference people read back, so it stays on one
   line even if the column has to be wider than the text beside it. */
.cgm-fr .reqno { white-space: nowrap; }
.cgm-fr .muted { color: #6b7280; }
.cgm-fr .note { display: block; font-size: 9px; color: #6b7280; margin-top: 2px; font-style: italic; }
.cgm-fr .neg { color: #9f1239; }
.cgm-fr .pos { color: #166534; }

.cgm-fr tfoot td { border-top: 1.5px solid #171717; font-weight: 800; padding: 6px; }

.cgm-fr.compact table.lines td, .cgm-fr.compact table.lines th { padding: 3.5px 5px; }
.cgm-fr.compact { font-size: 9.5px; }
.cgm-fr.ultra-compact table.lines td, .cgm-fr.ultra-compact table.lines th { padding: 2.5px 4px; }
.cgm-fr.ultra-compact { font-size: 9px; }

.cgm-fr .sigs { width: 100%; border-collapse: collapse; margin-top: 18px; page-break-inside: avoid; }
.cgm-fr .sigs td { width: 33.33%; padding: 0 14px 0 0; vertical-align: bottom; }
.cgm-fr .sig-line { border-top: 1px solid #171717; margin-top: 34px; padding-top: 3px; font-size: 9px; }
.cgm-fr .sig-role { font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; font-size: 8.5px; color: #6b7280; }
.cgm-fr .sig-name { font-weight: 700; }

.cgm-fr .remarks { margin-top: 10px; border: 1px solid #e5e7eb; border-left: 3px solid #8b1a1a;
  padding: 6px 9px; font-size: 9.5px; page-break-inside: avoid; }
.cgm-fr .remarks .lbl { font-size: 8.5px; text-transform: uppercase; letter-spacing: 0.5px; color: #6b7280; font-weight: 700; }
</style>

<div class="cgm-fr {{ density }}">

  <table class="head">
    <tr>
      <td>
        <div class="title">{{ _("Funding Request") }}</div>
        <div class="subtitle">{{ doc.company }}</div>
      </td>
      <td>
        <table class="meta">
          <tr><td class="k">{{ _("Request No") }}</td><td class="v">{{ doc.name }}</td></tr>
          <tr><td class="k">{{ _("Date") }}</td><td class="v">{{ frappe.format(doc.posting_date, {"fieldtype": "Date"}) or "-" }}</td></tr>
          <tr><td class="k">{{ _("Status") }}</td><td class="v">
            {%- set st = doc.workflow_state or "" -%}
            {%- if "Reject" in st %}{% set cls = "chip-rejected" %}
            {%- elif "Approv" in st or "Paid" in st or "Funded" in st %}{% set cls = "chip-approved" %}
            {%- else %}{% set cls = "chip-neutral" %}{% endif -%}
            <span class="chip {{ cls }}">{{ st or _("Draft") }}</span>
          </td></tr>
        </table>
      </td>
    </tr>
  </table>

  {#- Totals first. Whoever signs this is deciding on these five numbers, so they
      should not have to add up a column to find them. Approved and Outstanding
      stay blank until an approval is actually recorded, matching the form. -#}
  <table class="band">
    <tr>
      <td><span class="lbl">{{ _("Requests") }}</span><span class="amt">{{ rows | length }}</span></td>
      <td><span class="lbl">{{ _("Requested") }}</span><span class="amt">{{ frappe.format_value(doc.total_requested or 0, {"fieldtype": "Currency"}, doc) }}</span></td>
      <td><span class="lbl">{{ _("Approved") }}</span><span class="amt">{{ frappe.format_value(recorded and doc.total_approved or 0, {"fieldtype": "Currency"}, doc) }}</span></td>
      <td><span class="lbl">{{ _("Disbursed") }}</span><span class="amt">{{ frappe.format_value(doc.total_funded or 0, {"fieldtype": "Currency"}, doc) }}</span></td>
      <td><span class="lbl">{{ _("Outstanding") }}</span><span class="amt out">{{ frappe.format_value(recorded and doc.outstanding or 0, {"fieldtype": "Currency"}, doc) }}</span></td>
    </tr>
  </table>

  <table class="lines">
    <thead>
      <tr>
        <th class="idx">#</th>
        <th class="reqno">{{ _("Requisition") }}</th>
        <th>{{ _("Requester") }}</th>
        <th>{{ _("Items") }}</th>
        <th>{{ _("Project") }}</th>
        <th>{{ _("Decision") }}</th>
        <th class="num">{{ _("Requested") }}</th>
        <th class="num">{{ _("Approved") }}</th>
        <th class="num">{{ _("Variance") }}</th>
        <th class="num">{{ _("Disbursed") }}</th>
      </tr>
    </thead>
    <tbody>
      {%- for row in rows %}
      <tr>
        <td class="idx">{{ loop.index }}</td>
        <td class="reqno">{{ row.material_request }}</td>
        <td>{{ row.employee_name or row.employee or "-" }}</td>
        <td>{{ row.item_summary or row.description or "-" }}</td>
        <td class="muted">{{ row.project or "-" }}</td>
        <td>
          {%- if row.decision == "Approved" %}<span class="chip chip-approved">{{ _("Approved") }}</span>
          {%- elif row.decision == "Rejected" %}<span class="chip chip-rejected">{{ _("Rejected") }}</span>
          {%- else %}<span class="chip chip-neutral">{{ _("Pending") }}</span>{% endif -%}
          {#- The reason is the audit trail for any amount that moved, so it is
              printed with the row rather than left on screen. -#}
          {%- if row.decision == "Rejected" and row.rejection_reason %}
            <span class="note">{{ row.rejection_reason }}</span>
          {%- elif row.adjustment_reason %}
            <span class="note">{{ row.adjustment_reason }}</span>
          {%- endif %}
        </td>
        <td class="num">{{ frappe.format_value(row.requested_amount or 0, {"fieldtype": "Currency"}, doc) }}</td>
        {#- Approved and Variance stay blank until the row is actually decided.
            A pending row carries approved_amount 0, which rendered as a full
            negative variance - "Sh -1,000.00" against a request nobody had
            turned down yet. On a sheet someone signs, that is not a rounding
            detail, it reads as a decision that was never made. -#}
        {%- if row.decision == "Approved" %}
        <td class="num">{{ frappe.format_value(row.approved_amount or 0, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num {% if (row.variance or 0) < 0 %}neg{% elif (row.variance or 0) > 0 %}pos{% endif %}">
          {{ frappe.format_value(row.variance or 0, {"fieldtype": "Currency"}, doc) }}
        </td>
        {%- else %}
        <td class="num muted">-</td>
        <td class="num muted">-</td>
        {%- endif %}
        <td class="num">{{ frappe.format_value(row.funded_amount or 0, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
      {%- endfor %}
      {%- if not rows %}
      <tr><td colspan="10" class="muted" style="text-align:center;padding:14px;">{{ _("No material requests on this funding request.") }}</td></tr>
      {%- endif %}
    </tbody>
    {%- if rows %}
    <tfoot>
      <tr>
        <td colspan="6">{{ _("Total") }} - {{ approved_rows | length }} {{ _("approved") }}{% if rejected_rows %}, {{ rejected_rows | length }} {{ _("rejected") }}{% endif %}</td>
        <td class="num">{{ frappe.format_value(doc.total_requested or 0, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">{{ frappe.format_value(recorded and doc.total_approved or 0, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">{{ frappe.format_value(recorded and doc.total_variance or 0, {"fieldtype": "Currency"}, doc) }}</td>
        <td class="num">{{ frappe.format_value(doc.total_funded or 0, {"fieldtype": "Currency"}, doc) }}</td>
      </tr>
    </tfoot>
    {%- endif %}
  </table>

  {%- if doc.remarks %}
  <div class="remarks">
    <span class="lbl">{{ _("Remarks") }}</span>
    <div>{{ doc.remarks }}</div>
  </div>
  {%- endif %}

  {#- Three signatures because that is the control the workflow enforces: the
      person who raised it cannot be the person who approved it. -#}
  <table class="sigs">
    <tr>
      <td>
        <div class="sig-line">
          <span class="sig-role">{{ _("Requested by") }}</span><br>
          <span class="sig-name">{{ frappe.db.get_value("User", doc.submitted_by, "full_name") or doc.submitted_by or "" }}</span>
        </div>
      </td>
      <td>
        <div class="sig-line">
          <span class="sig-role">{{ _("Approved by") }}</span><br>
          <span class="sig-name">{{ frappe.db.get_value("User", doc.approved_by, "full_name") or doc.approved_by or "" }}</span>
          {%- if doc.approval_date %}<br><span class="muted">{{ frappe.format(doc.approval_date, {"fieldtype": "Date"}) }}</span>{% endif %}
        </div>
      </td>
      <td>
        <div class="sig-line">
          <span class="sig-role">{{ _("Disbursed by") }}</span><br>
          <span class="muted">{{ _("Name, signature and date") }}</span>
        </div>
      </td>
    </tr>
  </table>

</div>
